package com.opensocket.aievent.core.iam.persistence.repository;
import com.opensocket.aievent.core.iam.authentication.application.port.out.SecurityEpochPort;import com.opensocket.aievent.core.iam.persistence.dao.IamAuthenticationDao;import com.opensocket.aievent.core.iam.security.contract.SecurityEpoch;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;
@DatabaseRepositoryAdapter public class MybatisSecurityEpochAdapter implements SecurityEpochPort{private final IamAuthenticationDao dao;public MybatisSecurityEpochAdapter(IamAuthenticationDao dao){this.dao=dao;}public SecurityEpoch current(String tenant,String principal){long global=dao.findGlobalSecurityEpoch();long globalPrincipal=dao.findGlobalPrincipalSecurityEpoch(principal);if(tenant==null||tenant.isBlank())return new SecurityEpoch(global,0,globalPrincipal);return new SecurityEpoch(global,dao.findTenantSecurityEpoch(tenant),Math.max(globalPrincipal,dao.findPrincipalSecurityEpoch(tenant,principal)));}public SecurityEpoch increment(String tenant,String principal,String actor){if(tenant==null||tenant.isBlank()){dao.incrementPrincipalSecurityEpoch("",principal,actor);return current("",principal);}dao.incrementTenantSecurityEpoch(tenant,actor);dao.incrementPrincipalSecurityEpoch(tenant,principal,actor);return current(tenant,principal);}}
